/* 1.7.5 mobile performance: responsive hero image with a stable box and high priority. */
.g-hero-platform{isolation:isolate}
.g-hero-platform .g-hero-bg{position:absolute;inset:0;display:block;width:100%;height:100%;object-fit:cover;object-position:center;z-index:0}
.g-hero-platform::before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,14,24,.96) 0%,rgba(5,14,24,.77) 46%,rgba(5,14,24,.25) 100%);z-index:1;pointer-events:none}
.g-hero-platform::after{z-index:1}
.g-hero-platform .g-hero-content{position:relative;z-index:2}
@media(max-width:650px){
 .g-hero-platform::before{background:linear-gradient(180deg,rgba(5,14,24,.88),rgba(5,14,24,.78))}
}

